def mean(xs):
    if len(xs) == 0:
        raise ValueError("Cannot compute mean of empty list")
    return sum(xs) / len(xs)


def median(xs):
    if len(xs) == 0:
        raise ValueError("Cannot compute median of empty list")
    s = sorted(xs)
    n = len(s)
    mid = n // 2
    if n % 2 == 1:
        return s[mid]
    return (s[mid - 1] + s[mid]) / 2


def clamp(x, lo, hi):
    return max(lo, min(hi, x))
